use std::fmt::Write as _;

use crate::emit_web::ts_str;
use crate::model::InterfaceBundle;

pub fn render_i18n_generated_ts(bundle: &InterfaceBundle) -> String {
    let mut out = String::new();
    out.push_str(concat!(
        "// SPDX-",
        "License-Identifier: Apache-2.0\n",
        "// SPDX-FileCopyrightText: The Guardrails ADR Authors\n",
        "// @generated by grdr-interface-gen from contracts/interface/. Do not edit by hand.\n\n",
    ));

    out.push_str("export type LocaleDirection = \"ltr\" | \"rtl\";\n");
    out.push_str("export type LocaleScript = \"latn\" | \"cyrl\" | \"arab\" | \"jpan\";\n");
    out.push_str("export type LocaleCode = ");
    let locale_union: Vec<String> = bundle.locales.iter().map(|l| ts_str(&l.tag)).collect();
    out.push_str(&locale_union.join(" | "));
    out.push_str(";\n\n");

    out.push_str("export const SUPPORTED_LOCALES = [\n");
    for loc in &bundle.locales {
        let aliases: Vec<String> = loc.aliases.iter().map(|a| ts_str(a)).collect();
        let _ = writeln!(
            out,
            "  {{ tag: {}, nativeName: {}, tier: {}, script: {}, direction: {}, fallback: {}, aliases: [{}] }},",
            ts_str(&loc.tag),
            ts_str(&loc.native_name),
            ts_str(&loc.tier),
            ts_str(&loc.script),
            ts_str(&loc.direction),
            ts_str(&loc.fallback),
            aliases.join(", "),
        );
    }
    out.push_str("] as const;\n\n");

    let _ = writeln!(
        out,
        "export const BRAND_NAME = {};",
        ts_str(&bundle.vocabulary.brand_name)
    );
    let _ = writeln!(
        out,
        "export const BRAND_SHORT_NAME = {};\n",
        ts_str(&bundle.vocabulary.brand_short_name)
    );

    out.push_str("export const VOCABULARY_TERMS = {\n");
    for term in &bundle.vocabulary.terms {
        let _ = writeln!(
            out,
            "  {}: {{ term: {}, translate: {} }},",
            ts_str(&term.key),
            ts_str(&term.term),
            term.translate,
        );
    }
    out.push_str("} as const;\n\n");

    out.push_str("export const ICON_REGISTRY = {\n");
    for icon in &bundle.icons {
        let _ = writeln!(
            out,
            "  {}: {{ lucide: {}, mirror: {} }},",
            ts_str(&icon.key),
            ts_str(&icon.lucide),
            icon.mirror,
        );
    }
    out.push_str("} as const;\n\n");

    out.push_str("export const HARNESS_CATALOG_ICONS = [\n");
    for h in &bundle.harness_icons {
        let aliases: Vec<String> = h.aliases.iter().map(|a| ts_str(a)).collect();
        let _ = writeln!(
            out,
            "  {{ id: {}, displayName: {}, vendor: {}, kind: {}, aliases: [{}], simpleIcon: {}, lucide: {}, tone: {} }},",
            ts_str(&h.id),
            ts_str(&h.display_name),
            ts_str(&h.vendor),
            ts_str(&h.kind),
            aliases.join(", "),
            ts_str(&h.simple_icon),
            ts_str(&h.lucide),
            ts_str(&h.tone),
        );
    }
    out.push_str("] as const;\n\n");

    out.push_str("export const OS_CATALOG_ICONS = [\n");
    for os in &bundle.os_icons {
        let aliases: Vec<String> = os.aliases.iter().map(|a| ts_str(a)).collect();
        let _ = writeln!(
            out,
            "  {{ id: {}, displayName: {}, aliases: [{}], simpleIcon: {}, lucide: {}, tone: {} }},",
            ts_str(&os.id),
            ts_str(&os.display_name),
            aliases.join(", "),
            ts_str(&os.simple_icon),
            ts_str(&os.lucide),
            ts_str(&os.tone),
        );
    }
    out.push_str("] as const;\n\n");

    out.push_str("export const PRESENTATION_REGISTRY = [\n");
    for entry in &bundle.presentations {
        let desc = match &entry.description {
            Some(d) => ts_str(d),
            None => "null".to_owned(),
        };
        let _ = writeln!(
            out,
            "  {{ enumName: {}, value: {}, labelKey: {}, descriptionKey: {desc}, iconKey: {}, tone: {} }},",
            ts_str(&entry.enum_name),
            ts_str(&entry.value),
            ts_str(&entry.label),
            ts_str(&entry.icon),
            ts_str(&entry.tone),
        );
    }
    out.push_str("] as const;\n\n");

    out.push_str("export const INTERFACE_ROUTES = [\n");
    for route in &bundle.routes {
        let scopes: Vec<String> = route.scopes.iter().map(|s| ts_str(s)).collect();
        let _ = writeln!(
            out,
            "  {{ id: {}, titleKey: {}, iconKey: {}, area: {}, scopes: [{}], requires: {}, path: {}, shellNav: {} }},",
            ts_str(&route.id),
            ts_str(&route.title),
            ts_str(&route.icon),
            ts_str(&route.area),
            scopes.join(", "),
            ts_str(&route.requires),
            ts_str(&route.path),
            route.shell_nav,
        );
    }
    out.push_str("] as const;\n\n");

    out.push_str("export type InterfaceRouteId = (typeof INTERFACE_ROUTES)[number][\"id\"];\n");
    out.push_str(
        "export type AllConsoleRouteId = Extract<(typeof INTERFACE_ROUTES)[number], { area: \"console\" }>[\"id\"];\n",
    );
    out.push_str(
        "export type ConsoleRouteId = Extract<(typeof INTERFACE_ROUTES)[number], { area: \"console\"; shellNav: true }>[\"id\"];\n",
    );
    out.push_str(
        "export type AllOperatorRouteId = Extract<(typeof INTERFACE_ROUTES)[number], { area: \"operator\" }>[\"id\"];\n",
    );
    out.push_str(
        "export type OperatorRouteId = Extract<(typeof INTERFACE_ROUTES)[number], { area: \"operator\"; shellNav: true }>[\"id\"];\n\n",
    );

    out.push_str("export const MESSAGES = {\n");
    for msg in &bundle.messages {
        let _ = writeln!(out, "  {}: {},", ts_str(&msg.id), ts_str(&msg.msg));
    }
    out.push_str("} as const;\n\n");
    out.push_str("export type MessageKey = keyof typeof MESSAGES;\n\n");

    out.push_str(
        "export const TRANSLATIONS: Record<string, Partial<Record<MessageKey, string>>> = {\n",
    );
    for tr in &bundle.translations {
        let _ = writeln!(out, "  {}: {{", ts_str(&tr.locale_tag));
        for (id, val) in &tr.entries {
            if bundle.messages.iter().any(|m| m.id == *id) {
                let _ = writeln!(out, "    {}: {},", ts_str(id), ts_str(val));
            }
        }
        out.push_str("  },\n");
    }
    out.push_str("};\n\n");

    write_mf2_runtime(&mut out);
    out
}

fn write_mf2_runtime(out: &mut String) {
    out.push_str(
        r#"export type MessageArgs = Record<string, string | number | boolean>;

const LOCALE_STORAGE_KEY = "grdr_locale";
const localeListeners = new Set<(locale: LocaleCode) => void>();

export function getLocaleMeta(locale: LocaleCode) {
  return SUPPORTED_LOCALES.find((item) => item.tag === locale) ?? SUPPORTED_LOCALES[0];
}

export function resolveLocaleTag(raw: string | null | undefined): LocaleCode | null {
  if (!raw) return null;
  const norm = raw.trim().toLowerCase();
  for (const loc of SUPPORTED_LOCALES) {
    if (loc.tag.toLowerCase() === norm) return loc.tag;
    if ((loc.aliases as readonly string[]).some((alias) => alias.toLowerCase() === norm)) {
      return loc.tag;
    }
  }
  const base = norm.split(/[-_]/)[0];
  if (base) {
    for (const loc of SUPPORTED_LOCALES) {
      if (loc.tag.toLowerCase() === base || loc.tag.toLowerCase().startsWith(`${base}-`)) {
        return loc.tag;
      }
    }
  }
  return null;
}

function detectInitialLocale(): LocaleCode {
  try {
    if (typeof globalThis.location !== "undefined" && globalThis.location.search) {
      const fromQuery = new URLSearchParams(globalThis.location.search).get("locale");
      const resolvedQuery = resolveLocaleTag(fromQuery);
      if (resolvedQuery) return resolvedQuery;
    }
    if (typeof globalThis.localStorage !== "undefined") {
      const stored = globalThis.localStorage.getItem(LOCALE_STORAGE_KEY);
      const resolvedStored = resolveLocaleTag(stored);
      if (resolvedStored) return resolvedStored;
    }
  } catch {
    // ignore storage/location errors in constrained environments
  }
  return "en-US";
}

let activeLocale: LocaleCode = detectInitialLocale();

export function syncDocumentLocale(locale: LocaleCode): void {
  if (typeof document === "undefined") return;
  const meta = getLocaleMeta(locale);
  const root = document.documentElement;
  root.setAttribute("lang", meta.tag);
  root.setAttribute("dir", meta.direction);
  root.setAttribute("data-script", meta.script);
}

export function getLocale(): LocaleCode {
  return activeLocale;
}

export function initLocale(next: LocaleCode | string): LocaleCode {
  const resolved = resolveLocaleTag(next) ?? "en-US";
  activeLocale = resolved;
  return activeLocale;
}

export function setLocale(next: LocaleCode | string): LocaleCode {
  const resolved = resolveLocaleTag(next) ?? "en-US";
  try {
    if (typeof globalThis.localStorage !== "undefined") {
      globalThis.localStorage.setItem(LOCALE_STORAGE_KEY, resolved);
    }
  } catch {
    // ignore storage errors in constrained environments
  }
  if (activeLocale !== resolved) {
    activeLocale = resolved;
    syncDocumentLocale(resolved);
    for (const listener of localeListeners) {
      listener(resolved);
    }
  } else {
    syncDocumentLocale(resolved);
  }
  return activeLocale;
}

export function subscribeLocale(listener: (locale: LocaleCode) => void): () => void {
  localeListeners.add(listener);
  return () => {
    localeListeners.delete(listener);
  };
}

function formatNumberValue(val: number, localeTag: string): string {
  try {
    const intlLocale = localeTag === "en-XA" ? "en-US" : localeTag === "ar-XB" ? "ar" : localeTag === "ja-XC" ? "ja-JP" : localeTag;
    return new Intl.NumberFormat(intlLocale).format(val);
  } catch {
    return String(val);
  }
}

function selectPluralCategory(val: number, localeTag: string): string {
  try {
    const intlLocale = localeTag === "en-XA" ? "en-US" : localeTag === "ar-XB" ? "ar" : localeTag === "ja-XC" ? "ja-JP" : localeTag;
    return new Intl.PluralRules(intlLocale).select(val);
  } catch {
    return val === 1 ? "one" : "other";
  }
}

function resolveMf2Template(
  template: string,
  args: MessageArgs | undefined,
  localeTag: string,
  isolateOpen: string,
): string {
  let body = template.trim();
  const matchHeader = body.match(/^\.input\s+\{\$([A-Za-z0-9_]+)(?:\s+:number)?\}\s*\r?\n\.match\s+\$([A-Za-z0-9_]+)\s*\r?\n([\s\S]+)$/);
  if (matchHeader) {
    const varName = matchHeader[2];
    const variantsBlock = matchHeader[3];
    const rawVal = args?.[varName];
    const numVal = typeof rawVal === "number" ? rawVal : Number(rawVal ?? 0);
    const category = Number.isFinite(numVal) ? selectPluralCategory(numVal, localeTag) : "other";
    const exactStr = String(rawVal ?? "");
    const lines = variantsBlock.split(/\r?\n/);
    let fallbackBody = "";
    let matchedBody = "";
    for (const line of lines) {
      const m = line.match(/^\s*([^\s]+)\s+\{\{([\s\S]*)\}\}\s*$/);
      if (!m) continue;
      if (m[1] === exactStr || m[1] === category) {
        matchedBody = m[2];
        break;
      }
      if (m[1] === "*") {
        fallbackBody = m[2];
      }
    }
    body = matchedBody || fallbackBody || body;
  }

  return body.replace(/\{\$([A-Za-z0-9_]+)(?:\s+:(number|integer|string))?\}/g, (_full, name: string, kind?: string) => {
    const raw = args?.[name];
    if (raw === undefined) return `{${name}}`;
    const rendered =
      typeof raw === "number" && (kind === "number" || kind === "integer")
        ? formatNumberValue(raw, localeTag)
        : String(raw);
    return isolateOpen ? `${isolateOpen}${rendered}\u2069` : rendered;
  });
}

export function lookupMessage(
  locale: LocaleCode,
  key: MessageKey,
  args?: MessageArgs,
): string {
  const meta = getLocaleMeta(locale);
  const localized = TRANSLATIONS[locale]?.[key];
  const fallbackKey = meta.fallback as LocaleCode;
  const rawTemplate = localized ?? TRANSLATIONS[fallbackKey]?.[key] ?? MESSAGES[key];
  const isolateOpen =
    locale === "ar-XB" ? "\u2066" : meta.direction === "rtl" ? "\u2068" : "";
  const resolved = resolveMf2Template(rawTemplate, args, locale, isolateOpen);
  if (meta.tier !== "pseudo" || localized) {
    return resolved;
  }
  switch (locale) {
    case "en-XA":
      return `[${resolved} ~~~]`;
    case "ar-XB":
      return `\u2066${resolved}\u2069`;
    case "ja-XC":
      return `「${resolved}」`;
    default:
      return resolved;
  }
}

export function t(key: MessageKey, args?: MessageArgs, locale?: LocaleCode): string {
  return lookupMessage(locale ?? activeLocale, key, args);
}
"#,
    );
}
